1	// Soporte exclusivo de las pruebas de spec-0. Complementa factory/regresion/helpers.ts (que este spec no puede editar).
2	// Selectores tomados del código de Moodle 5.3 en entorno/.moodle-src/. Las aserciones que deciden si un criterio se
3	// cumple están en los .spec.ts; acá solo hay esperas y comprobaciones de que cada paso auxiliar terminó bien.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	import { bloquePregunta } from '../../../factory/regresion/helpers';
6	
7	export type TipoPregunta = 'multichoice' | 'truefalse' | 'essay';
8	export type Categoria = { id: string; contexto: string };
9	
10	type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };
11	
12	const configMoodle = (page: Page): Promise<ConfigMoodle> =>
13	  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);
14	
15	/** Nombre único que no contiene "Examen de regresión", para que abrirQuiz nunca tome este examen por QUIZ-REG. */
16	export const nombreUnico = (prefijo: string, proyecto: string) => `${prefijo} ${proyecto} ${Date.now()}`;
17	
18	export async function idCursoQA101(page: Page): Promise<number> {
19	  await page.goto('/course/view.php?name=QA101');
20	  return (await configMoodle(page)).courseId;
21	}
22	
23	// ---------------------------------------------------------------------------------------------------------
24	// Examen
25	
26	export async function abrirFormularioExamen(page: Page, curso: number) {
27	  await page.goto(`/course/modedit.php?add=quiz&course=${curso}&section=0`);
28	  await expect(page.locator('#id_introeditor_ifr')).toBeVisible();
29	}
30	
31	/** Guarda con "Save and display" y devuelve el cmid del examen creado o editado. */
32	export async function guardarExamen(page: Page): Promise<number> {
33	  await page.getByRole('button', { name: 'Save and display' }).click();
34	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
35	  return Number(new URL(page.url()).searchParams.get('id'));
36	}
37	
38	export async function crearExamen(page: Page, curso: number, nombre: string): Promise<number> {
39	  await abrirFormularioExamen(page, curso);
40	  await page.locator('#id_name').fill(nombre);
41	  return guardarExamen(page);
42	}
43	
44	export async function eliminarExamen(page: Page, cmid: number) {
45	  const { sesskey } = await configMoodle(page);
46	  await page.goto(`/course/mod.php?delete=${cmid}&sesskey=${sesskey}`);
47	  await page.getByRole('button', { name: 'Yes', exact: true }).click();
48	  await expect(page).toHaveURL(/course\/(view|section)\.php/);
49	}
50	
51	// ---------------------------------------------------------------------------------------------------------
52	// Banco de preguntas
53	
54	/** cmid del banco compartido de QA101, leído de la lista de bancos del curso. */
55	export async function cmidBanco(page: Page, curso: number): Promise<number> {
56	  await page.goto(`/question/banks.php?courseid=${curso}`);
57	  const banco = page.locator('.shared-banks .questioncount[data-cmid]').first();
58	  await expect(banco).toBeAttached();
59	  return Number(await banco.getAttribute('data-cmid'));
60	}
61	
62	export const urlCategorias = (banco: number) => `/question/bank/managecategories/category.php?cmid=${banco}`;
63	const urlBanco = (banco: number, c: Categoria) => `/question/edit.php?cmid=${banco}&cat=${c.id},${c.contexto}`;
64	
65	export const filaCategoria = (page: Page, nombre: string): Locator =>
66	  page.locator(`li.qbank_managecategories-item[data-categoryname=${JSON.stringify(nombre)}]`);
67	
68	export const filaPregunta = (page: Page, nombre: string): Locator =>
69	  page.locator('#categoryquestions tbody tr', { hasText: nombre });
70	
71	/**
72	 * Crea una categoría propia en el banco. Es necesaria porque el banco sembrado no tiene categoría por defecto
73	 * (question_bank_helper.php:660 usa skipdefaultcategory): sin esto, las preguntas caerían en Álgebra.
74	 */
75	export async function crearCategoria(page: Page, banco: number, nombre: string): Promise<Categoria> {
76	  await page.goto(urlCategorias(banco));
77	  // El botón recibe su evento cuando el componente reactivo termina de cargar el estado.
78	  await page.waitForLoadState('networkidle');
79	  await page.locator('#qbank_managecategories-addcategory [data-action="addeditcategory"]').click();
80	  const modal = page.locator('[data-region="modal"]').filter({ has: page.locator('input[name="name"]') });
81	  await modal.locator('input[name="name"]').fill(nombre);
82	  await modal.locator('[data-action="save"]').click();
83	  await expect(filaCategoria(page, nombre)).toHaveCount(1);
84	  await page.reload();
85	  const id = await filaCategoria(page, nombre).getAttribute('data-categoryid');
86	  const { contextid } = await configMoodle(page);
87	  return { id: String(id), contexto: String(contextid) };
88	}
89	
90	/** Escribe en un editor TinyMCE. `iframe` es el selector CSS de su iframe. */
91	export async function escribirEditor(page: Page, iframe: string, texto: string) {
92	  await expect(page.locator(iframe)).toBeVisible();
93	  const cuerpo = page.frameLocator(iframe).locator('body');
94	  await cuerpo.click();
95	  await cuerpo.fill(texto);
96	}
97	
98	/** Crea una pregunta desde el botón "Create a new question ..." del banco, dentro de la categoría indicada. */
99	export async function crearPregunta(page: Page, banco: number, categoria: Categoria, tipo: TipoPregunta, nombre: string) {
100	  await page.goto(urlBanco(banco, categoria));
101	  await page.getByRole('button', { name: /create a new question/i }).click();
102	  await page.locator(`#item_qtype_${tipo}`).check();
103	  await page.locator('#chooserform input.submitbutton').click();
104	  await expect(page).toHaveURL(/question\/bank\/editquestion\/question\.php/);
105	
106	  await page.locator('#id_name').fill(nombre);
107	  await escribirEditor(page, '#id_questiontext_ifr', `Enunciado de ${nombre}`);
108	  if (tipo === 'multichoice') {
109	    await escribirEditor(page, '#id_answer_0_ifr', 'Correcta');
110	    await page.locator('#id_fraction_0').selectOption({ label: '100%' });
111	    await escribirEditor(page, '#id_answer_1_ifr', 'Incorrecta');
112	  } else if (tipo === 'truefalse') {
113	    await page.locator('#id_correctanswer').selectOption({ label: 'True' });
114	  }
115	  await page.locator('#id_submitbutton').click();
116	  await expect(page).toHaveURL(/question\/edit\.php/);
117	  await expect(filaPregunta(page, nombre)).toHaveCount(1);
118	}
119	
120	/** Add > from question bank > Switch bank > filtro de categoría > Add selected questions to the quiz. */
121	export async function agregarDesdeBanco(page: Page, examen: number, banco: number, categoria: string, preguntas: string[]) {
122	  await page.goto(`/mod/quiz/edit.php?cmid=${examen}`);
123	  await page.waitForLoadState('networkidle');
124	  await page.locator('.last-add-menu a[data-bs-toggle="dropdown"]').click();
125	  await page.locator('.last-add-menu [data-action="questionbank"]').click();
126	
127	  // El modal abre en el banco privado del examen; las preguntas están en el banco del curso.
128	  await page.locator('#switch-question-bank').click();
129	  // bank_switcher.js oculta esta selección justo antes de registrar el clic de los enlaces.
130	  await expect(page.locator('.search-banks .form-autocomplete-selection.d-none')).toHaveCount(1);
131	  await page.locator(`a[data-newmodid="${banco}"]`).click();
132	
133	  const filtro = page.locator('[data-filter-type="category"]');
134	  const entrada = filtro.locator('div.form-autocomplete-input input');
135	  await entrada.click();
136	  await entrada.fill(categoria);
137	  await filtro.locator('.form-autocomplete-suggestions li', { hasText: categoria }).click();
138	  await page.locator('[data-filteraction="apply"]').click();
139	
140	  for (const nombre of preguntas) {
141	    await filaPregunta(page, nombre).locator('input[type="checkbox"]').check();
142	  }
143	  await page.getByRole('button', { name: 'Add selected questions to the quiz' }).click();
144	  await expect(page).toHaveURL(/mod\/quiz\/edit\.php/);
145	}
146	
147	/** Borra todas las preguntas de la categoría con la confirmación del banco y comprueba que ya no se listan. */
148	export async function eliminarPreguntas(page: Page, banco: number, categoria: Categoria) {
149	  await page.goto(urlBanco(banco, categoria));
150	  const nombres = await page.locator('#categoryquestions tbody input[type="checkbox"]')
151	    .evaluateAll((casillas) => casillas.map((c) => (c as HTMLInputElement).name));
152	  const ids = nombres.filter((n) => /^q\d+$/.test(n));
153	  if (!ids.length) return;
154	  const { sesskey } = await configMoodle(page);
155	  const parametros = new URLSearchParams({
156	    deleteselected: ids[0].slice(1),
157	    deleteall: '1',
158	    sesskey,
159	    cmid: String(banco),
160	    returnurl: `/question/edit.php?cmid=${banco}`,
161	  });
162	  ids.forEach((q) => parametros.set(q, '1'));
163	  await page.goto(`/question/bank/deletequestion/delete.php?${parametros}`);
164	  await page.getByRole('button', { name: 'Delete', exact: true }).click();
165	  await expect(page).toHaveURL(/question\/edit\.php/);
166	  await page.goto(urlBanco(banco, categoria));
167	  await expect(page.locator('#categoryquestions tbody tr')).toHaveCount(0);
168	}
169	
170	export async function eliminarCategoria(page: Page, banco: number, categoria: Categoria) {
171	  const { sesskey } = await configMoodle(page);
172	  await page.goto(`${urlCategorias(banco)}&delete=${categoria.id}&sesskey=${sesskey}`);
173	  await expect(page).toHaveURL(/managecategories\/category\.php/);
174	}
175	
176	// ---------------------------------------------------------------------------------------------------------
177	// Intento y calificación
178	
179	/** Radio de una opción, con el mismo criterio de nombre accesible que elegir() en helpers.ts. */
180	export function opcion(page: Page, pregunta: number, texto: string): Locator {
181	  return bloquePregunta(page, pregunta).getByRole('radio', { name: new RegExp(`^([a-z0-9]+\\. )?${texto}$`, 'i') });
182	}
183	
184	/** Celda de estado de una pregunta en la tabla de summary.php. */
185	export const estadoEnResumen = (page: Page, pregunta: number): Locator =>
186	  page.locator(`table.quizsummaryofattempt tr.quizsummary${pregunta} td.c1`);
187	
188	/** Desde la última página del intento va a summary.php, sin enviar. */
189	export async function irAlResumen(page: Page) {
190	  await page.getByRole('button', { name: /finish attempt/i }).click();
191	  await expect(page).toHaveURL(/summary\.php/);
192	}
193	
194	export const idIntento = (page: Page) => Number(new URL(page.url()).searchParams.get('attempt'));
195	
196	/**
197	 * Celdas de la columna Time del historial de respuestas de comment.php. prepararCaptura no las cubre y la fábrica
198	 * no puede editar helpers.ts desde este spec. Se ubican por el texto del encabezado, no por posición.
199	 */
200	export async function celdasTiempoHistorial(page: Page): Promise<Locator> {
201	  const tabla = page.locator('div.responsehistoryheader table');
202	  const encabezados = await tabla.locator('thead th').allTextContents();
203	  const columna = encabezados.findIndex((t) => t.trim() === 'Time');
204	  expect(columna, `Encabezados del historial: ${encabezados.join(', ')}`).not.toEqual(-1);
205	  return tabla.locator(`tbody tr > :nth-child(${columna + 1})`);
206	}
