20	export function lintPHP(specDir) {
21	  const fallos = [];
22	  for (const f of archivos(`${specDir}/codigo`, (x) => x.endsWith('.php'))) {
23	    // El contenedor web no monta la raíz del repo: se pasa el contenido por stdin (php -l lee stdin).
24	    const r = sh(`${DC} exec -T web php -l`, { input: fs.readFileSync(path.join(RAIZ, f), 'utf8') });
25	    if (r.code !== 0) fallos.push(`${f}: ${(r.out + r.err).trim()}`);
26	  }
27	  return fallos;
28	}
