30	/** Copia los plugins generados al árbol de Moodle y corre la actualización. */
31	export function desplegar(specDir) {
32	  const plugins = pluginsDe(specDir);
33	  for (const p of plugins) {
34	    const destino = path.join(MOODLE_SRC, p.rel);
35	    fs.rmSync(destino, { recursive: true, force: true });
36	    fs.cpSync(path.join(RAIZ, specDir, 'codigo', p.rel), destino, { recursive: true });
37	  }
38	  const up = php('admin/cli/upgrade.php --non-interactive --allow-unstable');
39	  const purge = php('admin/cli/purge_caches.php');
40	  return { plugins, ok: up.code === 0 && !/error|exception/i.test(up.out.slice(-2000)), salida: (up.out + up.err).slice(-6000), purge: purge.code === 0 };
41	}
