43	/** Desinstala y quita del árbol los plugins de un spec (para la prueba "sin la funcionalidad"). */
44	export function retirar(specDir) {
45	  const plugins = pluginsDe(specDir).filter((p) => p.componente);
46	  if (!plugins.length) return { ok: true, salida: 'sin plugins' };
47	  const r = php(`admin/cli/uninstall_plugins.php --plugins=${plugins.map((p) => p.componente).join(',')} --run`);
48	  for (const p of plugins) fs.rmSync(path.join(MOODLE_SRC, p.rel), { recursive: true, force: true });
49	  php('admin/cli/purge_caches.php');
50	  return { ok: r.code === 0, salida: (r.out + r.err).slice(-4000) };
51	}
